<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Alpaca Walk</title>
<style>
  html, body {
    margin: 0;
    width: 100%;
    height: 100%;
    overflow: hidden;
    background: #fde9cf;
  }
  svg {
    display: block;
    width: 100vw;
    height: 100vh;
  }
</style>
</head>
<body>
<svg id="scene" viewBox="0 0 1280 720" preserveAspectRatio="xMidYMid slice" xmlns="http://www.w3.org/2000/svg">
  <defs>
    <linearGradient id="sky" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="#9fd6ea"/>
      <stop offset="0.6" stop-color="#fbe7d0"/>
      <stop offset="1" stop-color="#ffd9ae"/>
    </linearGradient>
    <radialGradient id="sunGlow">
      <stop offset="0" stop-color="#fff8dc" stop-opacity="1"/>
      <stop offset="0.4" stop-color="#ffeaae" stop-opacity="0.8"/>
      <stop offset="1" stop-color="#ffeaae" stop-opacity="0"/>
    </radialGradient>
    <linearGradient id="groundGrad" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="#8dbb6e"/>
      <stop offset="1" stop-color="#5a8b4c"/>
    </linearGradient>
    <filter id="soft" x="-30%" y="-30%" width="160%" height="160%">
      <feGaussianBlur stdDeviation="7"/>
    </filter>
    <filter id="lift" x="-20%" y="-20%" width="140%" height="140%">
      <feDropShadow dx="0" dy="8" stdDeviation="7" flood-color="#5a3d2a" flood-opacity="0.22"/>
    </filter>
  </defs>

  <!-- Sky -->
  <rect width="1280" height="720" fill="url(#sky)"/>
  <circle cx="1000" cy="160" r="170" fill="url(#sunGlow)"/>
  <circle cx="1000" cy="160" r="50" fill="#fff7dc"/>

  <!-- Clouds (scrolling) -->
  <g id="clouds"></g>

  <!-- Parallax hills & scenery -->
  <g id="farLayer"></g>
  <g id="midLayer"></g>
  <g id="nearLayer"></g>

  <!-- Ground -->
  <rect x="0" y="600" width="1280" height="120" fill="url(#groundGrad)"/>
  <rect x="0" y="600" width="1280" height="3" fill="#b9d996" opacity="0.7"/>
  <g id="flowerLayer"></g>
  <g id="grassLayer"></g>

  <!-- Alpaca shadow -->
  <ellipse id="shadow" cx="640" cy="604" rx="175" ry="14" fill="#2f4a22" opacity="0.25" filter="url(#soft)"/>

  <!-- Alpaca -->
  <g id="alpaca" filter="url(#lift)">
    <g id="legsFar"></g>

    <g id="torso">
      <g id="tail">
        <circle cx="524" cy="372" r="15" fill="#f1e6d1"/>
        <circle cx="512" cy="386" r="13" fill="#f5ecdc"/>
        <circle cx="530" cy="392" r="11" fill="#ebdcc2"/>
      </g>
      <!-- fleece body mass -->
      <g fill="#f4eadb">
        <circle cx="500" cy="412" r="44"/>
        <circle cx="552" cy="392" r="72"/>
        <circle cx="626" cy="374" r="84"/>
        <circle cx="706" cy="386" r="78"/>
        <circle cx="604" cy="428" r="64"/>
        <circle cx="676" cy="434" r="66"/>
        <circle cx="738" cy="420" r="46"/>
      </g>
      <!-- underbelly shade -->
      <ellipse cx="640" cy="448" rx="135" ry="26" fill="#e0cdac" opacity="0.45"/>
      <!-- top light -->
      <g fill="#fffdf6" opacity="0.75">
        <circle cx="610" cy="346" r="40"/>
        <circle cx="680" cy="350" r="34"/>
        <circle cx="560" cy="356" r="30"/>
        <circle cx="720" cy="360" r="26"/>
      </g>
      <!-- wool curls -->
      <g fill="none" stroke="#d6c2a0" stroke-width="2.2" stroke-linecap="round" opacity="0.55">
        <path d="M534 380 q7 -7 14 0"/>
        <path d="M578 362 q7 -7 14 0"/>
        <path d="M618 396 q7 -7 14 0"/>
        <path d="M660 376 q7 -7 14 0"/>
        <path d="M700 404 q7 -7 14 0"/>
        <path d="M566 414 q7 -7 14 0"/>
        <path d="M644 420 q7 -7 14 0"/>
        <path d="M688 440 q7 -7 14 0"/>
        <path d="M600 448 q7 -7 14 0"/>
        <path d="M740 388 q6 -6 12 0"/>
      </g>
    </g>

    <g id="neckGroup">
      <!-- neck -->
      <path d="M735 352 L795 204" stroke="#f4eadb" stroke-width="52" stroke-linecap="round"/>
      <g fill="#f4eadb">
        <circle cx="722" cy="360" r="46"/>
        <circle cx="742" cy="315" r="42"/>
        <circle cx="762" cy="270" r="38"/>
        <circle cx="780" cy="228" r="34"/>
        <circle cx="795" cy="196" r="30"/>
      </g>
      <path d="M752 318 L788 224" stroke="#dcc9a8" stroke-width="6" stroke-linecap="round" opacity="0.35"/>
      <g fill="#fffdf6" opacity="0.6">
        <circle cx="748" cy="300" r="14"/>
        <circle cx="770" cy="250" r="12"/>
      </g>

      <!-- ears (upright) -->
      <path d="M792 150 C778 110 776 70 786 46 C800 78 812 112 822 140 Z" fill="#d6c09a"/>
      <path d="M806 146 C800 106 804 70 818 50 C828 84 834 116 836 140 Z" fill="#ecdcbf"/>
      <path d="M806 136 C801 110 804 80 814 62 C822 88 826 112 828 134 Z" fill="#e7b9a2" opacity="0.8"/>

      <!-- head -->
      <ellipse cx="822" cy="160" rx="37" ry="28" fill="#f2e6cf" transform="rotate(-12 822 160)"/>
      <path d="M836 150 Q862 138 872 156 Q876 172 856 180 Q838 184 830 172 Z" fill="#efe0c6"/>
      <!-- topknot fleece -->
      <g fill="#fffaf0">
        <circle cx="806" cy="134" r="14"/>
        <circle cx="824" cy="127" r="16"/>
        <circle cx="842" cy="134" r="12"/>
      </g>
      <!-- cheek & eye -->
      <circle cx="838" cy="168" r="6" fill="#f2b8a0" opacity="0.45"/>
      <circle cx="828" cy="150" r="5.5" fill="#2a211b"/>
      <circle cx="830" cy="148" r="1.6" fill="#ffffff"/>
      <circle cx="867" cy="164" r="2.2" fill="#6b5444"/>
      <path d="M856 178 Q862 182 868 176" fill="none" stroke="#8a6b58" stroke-width="1.6" stroke-linecap="round"/>
    </g>

    <g id="legsNear"></g>
  </g>

  <!-- Foreground tufts -->
  <g id="fgLayer"></g>
</svg>

<script>
(() => {
  const TAU = Math.PI * 2;
  const W = 1280;
  const CYCLE = 1.4;      // seconds per full stride
  const HIP_AMP = 24;     // degrees
  const KNEE_AMP = 40;    // degrees of lift
  const $ = id => document.getElementById(id);
  const fract = x => x - Math.floor(x);
  const rnd = i => fract(Math.sin(i * 12.9898 + 78.233) * 43758.5453);
  const NS = 'http://www.w3.org/2000/svg';

  // ---------- Parallax scenery (periodic over 1280px, drawn from -1280..2560) ----------
  function hillPath(base, amp, seed) {
    let d = 'M-1280 720';
    for (let x = -1280; x <= 2560; x += 8) {
      const u = (x / W) * TAU;
      const y = base + amp * (
        Math.sin(u + seed) * 0.55 +
        Math.sin(2 * u + seed * 1.7) * 0.30 +
        Math.sin(3 * u + seed * 2.3) * 0.15
      );
      d += ` L${x} ${y.toFixed(1)}`;
    }
    return d + ' L2560 720 Z';
  }

  $('farLayer').innerHTML = `<path d="${hillPath(440, 30, 1.3)}" fill="#cfe3dc" opacity="0.95"/>
    <path d="${hillPath(452, 18, 4.1)}" fill="#c3dccf" opacity="0.6"/>`;

  let bushes = '';
  for (let i = -8; i < 16; i++) {
    const k = ((i % 8) + 8) % 8;
    const x = i * 160 + rnd(k) * 50;
    const y = 488 + rnd(k + 9) * 14;
    const r = 20 + rnd(k + 3) * 12;
    bushes += `<g fill="#9cc488">
      <circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="${r.toFixed(1)}"/>
      <circle cx="${(x + r * 0.9).toFixed(1)}" cy="${(y + 6).toFixed(1)}" r="${(r * 0.78).toFixed(1)}"/>
      <circle cx="${(x - r * 0.8).toFixed(1)}" cy="${(y + 8).toFixed(1)}" r="${(r * 0.7).toFixed(1)}"/>
    </g>`;
  }
  $('midLayer').innerHTML = `<path d="${hillPath(505, 26, 2.7)}" fill="#b3d5a4"/>${bushes}`;

  $('nearLayer').innerHTML = `<path d="${hillPath(566, 20, 5.9)}" fill="#9ccb83"/>`;

  // Clouds: positions in [0,1280), copied at -1280/0/+1280 for seamless wrap
  const cloudData = [[120, 110, 1.0], [430, 70, 0.8], [760, 150, 1.05], [1100, 70, 0.75]];
  const cloud = (x, y, s) => `<g fill="#ffffff" opacity="0.9">
      <ellipse cx="${x}" cy="${y}" rx="${60 * s}" ry="${22 * s}"/>
      <ellipse cx="${x - 30 * s}" cy="${y + 6 * s}" rx="${36 * s}" ry="${18 * s}"/>
      <ellipse cx="${x + 34 * s}" cy="${y + 8 * s}" rx="${40 * s}" ry="${18 * s}"/>
      <ellipse cx="${x + 6 * s}" cy="${y - 14 * s}" rx="${34 * s}" ry="${22 * s}"/>
    </g>`;
  let cl = '';
  for (let k = -1; k <= 1; k++) {
    for (const [x, y, s] of cloudData) cl += cloud(x + k * W, y, s);
  }
  $('clouds').innerHTML = cl;

  // Flowers in the meadow (period 12 across 1280px)
  const petalCols = ['#fff6e6', '#f7c6d0', '#ffe27a', '#d7c6f5'];
  let flowers = '';
  for (let i = -12; i < 24; i++) {
    const k = ((i % 12) + 12) % 12;
    const x = i * (W / 12) + rnd(k) * 30;
    const y = 628 + rnd(k + 5) * 72;
    const col = petalCols[Math.floor(rnd(k + 17) * petalCols.length)];
    const sc = 0.8 + rnd(k + 2) * 0.6;
    let petals = '';
    for (let p = 0; p < 5; p++) {
      const a = (p / 5) * TAU;
      petals += `<circle cx="${(x + Math.cos(a) * 4 * sc).toFixed(2)}" cy="${(y + Math.sin(a) * 4 * sc).toFixed(2)}" r="${(3 * sc).toFixed(2)}" fill="${col}"/>`;
    }
    flowers += `<line x1="${x.toFixed(2)}" y1="${y.toFixed(2)}" x2="${(x + 1.5).toFixed(2)}" y2="${(y + 14 * sc).toFixed(2)}" stroke="#4f7d40" stroke-width="1.6"/>
      ${petals}<circle cx="${x.toFixed(2)}" cy="${y.toFixed(2)}" r="${(2 * sc).toFixed(2)}" fill="#f2c24a"/>`;
  }
  $('flowerLayer').innerHTML = flowers;

  // Grass tufts (period 24)
  let tufts = '';
  for (let i = -24; i < 48; i++) {
    const k = ((i % 24) + 24) % 24;
    const x = i * (W / 24) + rnd(k) * 16;
    const y = 612 + rnd(k + 7) * 14;
    const s = 0.8 + rnd(k + 11) * 0.5;
    tufts += `<path d="M${x.toFixed(1)} ${y.toFixed(1)} q ${(-3 * s).toFixed(1)} ${(-9 * s).toFixed(1)} ${(-7 * s).toFixed(1)} ${(-14 * s).toFixed(1)}
      M${x.toFixed(1)} ${y.toFixed(1)} q ${(1 * s).toFixed(1)} ${(-11 * s).toFixed(1)} ${(2 * s).toFixed(1)} ${(-17 * s).toFixed(1)}
      M${x.toFixed(1)} ${y.toFixed(1)} q ${(4 * s).toFixed(1)} ${(-8 * s).toFixed(1)} ${(9 * s).toFixed(1)} ${(-12 * s).toFixed(1)}"
      fill="none" stroke="#4d7a3f" stroke-width="2" stroke-linecap="round"/>`;
  }
  $('grassLayer').innerHTML = tufts;

  // Foreground tufts (closest, fastest)
  let fg = '';
  for (let i = -10; i < 20; i++) {
    const k = ((i % 10) + 10) % 10;
    const x = i * (W / 10) + rnd(k + 40) * 60;
    const y = 716 + rnd(k + 50) * 6;
    const s = 1.6 + rnd(k + 60) * 0.6;
    fg += `<path d="M${x.toFixed(1)} ${y.toFixed(1)} q ${(-4 * s).toFixed(1)} ${(-12 * s).toFixed(1)} ${(-10 * s).toFixed(1)} ${(-20 * s).toFixed(1)}
      M${x.toFixed(1)} ${y.toFixed(1)} q ${(2 * s).toFixed(1)} ${(-14 * s).toFixed(1)} ${(3 * s).toFixed(1)} ${(-24 * s).toFixed(1)}
      M${x.toFixed(1)} ${y.toFixed(1)} q ${(6 * s).toFixed(1)} ${(-10 * s).toFixed(1)} ${(13 * s).toFixed(1)} ${(-16 * s).toFixed(1)}"
      fill="none" stroke="#3f6a35" stroke-width="2.6" stroke-linecap="round"/>`;
  }
  $('fgLayer').innerHTML = fg;

  // ---------- Alpaca legs ----------
  function leg(id, x, y, col) {
    return `<g id="${id}" transform="translate(${x} ${y})">
      <g class="up">
        <path d="M0 0 V80" stroke="${col}" stroke-width="30" stroke-linecap="round"/>
        <g class="lo" transform="translate(0 80)">
          <path d="M0 0 V72" stroke="${col}" stroke-width="20" stroke-linecap="round"/>
          <rect x="-11" y="62" width="22" height="12" rx="4" fill="#4a3b31"/>
        </g>
      </g>
    </g>`;
  }
  $('legsFar').innerHTML =
    leg('fBack', 556, 424, '#d6c3a1') +
    leg('fFront', 716, 424, '#d6c3a1');
  $('legsNear').innerHTML =
    leg('nBack', 546, 430, '#eee2cb') +
    leg('nFront', 728, 430, '#eee2cb');

  // Diagonal gait: front-near & back-far together; front-far & back-near together
  const legs = [
    { el: $('fBack'),  phi: 0,       amp: 22 },
    { el: $('fFront'), phi: Math.PI, amp: 24 },
    { el: $('nBack'),  phi: Math.PI, amp: 22 },
    { el: $('nFront'), phi: 0,       amp: 24 },
  ].map(l => ({ ...l, up: l.el.querySelector('.up'), lo: l.el.querySelector('.lo') }));

  const alpaca = $('alpaca');
  const neck = $('neckGroup');
  const tail = $('tail');
  const shadow = $('shadow');

  // Layer scroll speeds (px/s); ground matches the stance speed of the feet
  const layers = [
    { el: $('clouds'),    speed: 8 },
    { el: $('farLayer'),  speed: 14 },
    { el: $('midLayer'),  speed: 40 },
    { el: $('nearLayer'), speed: 70 },
    { el: $('flowerLayer'), speed: 178 },
    { el: $('grassLayer'),  speed: 178 },
    { el: $('fgLayer'),    speed: 260 },
  ];

  const start = performance.now();

  function frame(now) {
    const t = (now - start) / 1000;
    const p = (TAU * t) / CYCLE;

    // Legs
    for (const l of legs) {
      const q = p + l.phi;
      const hip = l.amp * Math.sin(q);                 // + rotates foot backward (stance)
      const knee = KNEE_AMP * Math.max(0, -Math.cos(q)); // fold lower leg during swing
      l.up.setAttribute('transform', `rotate(${hip.toFixed(2)})`);
      l.lo.setAttribute('transform', `translate(0 80) rotate(${knee.toFixed(2)})`);
    }

    // Body: two bobs per stride, gentle pitch
    const dy = -5 * (1 - Math.cos(2 * p)) / 2;
    const pitch = 0.9 * Math.sin(p);
    alpaca.setAttribute('transform', `translate(0 ${dy.toFixed(2)}) rotate(${pitch.toFixed(2)} 640 430)`);

    // Neck nods counter to the bob; tail sways
    neck.setAttribute('transform', `rotate(${(1.8 * Math.sin(2 * p + 0.6)).toFixed(2)} 735 360)`);
    tail.setAttribute('transform', `rotate(${(12 * Math.sin(p + 1.0)).toFixed(2)} 552 380)`);

    // Shadow breathes with the bob
    shadow.setAttribute('rx', (175 + dy * 2).toFixed(2));
    shadow.setAttribute('opacity', (0.25 + dy * 0.006).toFixed(3));

    // Parallax scrolling (seamless, period 1280)
    for (const L of layers) {
      const off = (t * L.speed) % W;
      L.el.setAttribute('transform', `translate(${(-off).toFixed(2)} 0)`);
    }

    requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);
})();
</script>
</body>
</html>
